INSERT INTO talora_training_seed(payload) VALUES ($talora_programs$[{"slug":"talora-business-analysis-2026","title":"Business Analysis Internship","category":"Business Analysis","short_description":"[[AZ]]\nReal biznes problemini araşdır, prosesləri modelləşdir və ölçülə bilən tələblər hazırla.\n\n[[EN]]\nInvestigate business problems, model processes and write measurable requirements.","description":"[[AZ]]\nBu, Talora platformasının 8 həftəlik portfel-yönümlü praktik təlim proqramıdır. Məqsəd: Real biznes problemini araşdır, prosesləri modelləşdir və ölçülə bilən tələblər hazırla. Real şirkətdə işə qəbul, maaş, fərdi mentor və ya sertifikat vədi verilmir. Tapşırıqlarda yalnız sintetik, şəxsi və ya istifadəsinə icazə verilən məlumatlardan istifadə et.\n\n[[EN]]\nThis is an eight-week Talora portfolio-oriented practical training program. Goal: Investigate business problems, model processes and write measurable requirements. It does not promise employment, salary, a dedicated mentor or a certificate. Use only synthetic, own or properly licensed data.","skills":["Business requirements","BPMN","User stories","KPI","UAT"],"requirements":["Əsas kompüter savadlılığı, müstəqil araşdırma və qeydlərin sistemləşdirilməsi","8 həftə ərzində həftəlik praktik iş üçün vaxt ayırmaq","Mənbələri göstərmək, məxfilik və müəlliflik hüquqlarına riayət etmək"],"responsibilities":["Hər həftə mövzuya uyğun tapşırıqları yerinə yetirmək","Nəticələri yoxlanıla bilən fayl və ya linklə təqdim etmək","Mənbələri, məhdudiyyətləri və öz töhfəsini izah etmək"],"benefits":["Yoxlanıla bilən praktik layihələr və portfel","Strukturlaşdırılmış 8 həftəlik öyrənmə planı","Tapşırıq nəticələrinin şəxsi CV və portfeldə nümayişi"],"tasks":[{"title":"Business Problem Discovery","description":"[[AZ]]\nProblemi bir cümlə ilə müəyyən et ;  Üç maraqlı tərəfin ehtiyaclarını müqayisə et ;  Problemi fakt və fərziyyələrə ayır.\n\n[[EN]]\nDefine the problem in one sentence ;  Compare needs of three stakeholders ;  Separate facts from assumptions.","instructions":"[[AZ]]\n## Məqsəd\nProblemi bir cümlə ilə müəyyən et ;  Üç maraqlı tərəfin ehtiyaclarını müqayisə et ;  Problemi fakt və fərziyyələrə ayır.\n\n## Addım-addım icra\n1. Problemi bir cümlə ilə müəyyən et.\n2. Üç maraqlı tərəfin ehtiyaclarını müqayisə et.\n3. Problemi fakt və fərziyyələrə ayır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nProblem statement və fərziyyə cədvəli. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDefine the problem in one sentence ;  Compare needs of three stakeholders ;  Separate facts from assumptions.\n\n## Step-by-step\n1. Define the problem in one sentence.\n2. Compare needs of three stakeholders.\n3. Separate facts from assumptions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nProblem statement and assumption table. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":1,"task_number":1,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Stakeholder Mapping","description":"[[AZ]]\nTəsirlənən beş rol müəyyən et ;  Influence-interest matrisi qur ;  Hər rol üçün müsahibə sualları hazırla.\n\n[[EN]]\nIdentify five impacted roles ;  Create an influence-interest matrix ;  Draft interview questions for each role.","instructions":"[[AZ]]\n## Məqsəd\nTəsirlənən beş rol müəyyən et ;  Influence-interest matrisi qur ;  Hər rol üçün müsahibə sualları hazırla.\n\n## Addım-addım icra\n1. Təsirlənən beş rol müəyyən et.\n2. Influence-interest matrisi qur.\n3. Hər rol üçün müsahibə sualları hazırla.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nStakeholder matrix və sual siyahısı. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nIdentify five impacted roles ;  Create an influence-interest matrix ;  Draft interview questions for each role.\n\n## Step-by-step\n1. Identify five impacted roles.\n2. Create an influence-interest matrix.\n3. Draft interview questions for each role.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nStakeholder matrix and interview guide. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":2,"task_number":2,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"As-Is Process Analysis","description":"[[AZ]]\nMövcud sifariş və ya müraciət axınını seç ;  Ən azı altı addımlı BPMN sxemi hazırla ;  Gözləmə və təkrar işi işarələ.\n\n[[EN]]\nChoose a current application or order flow ;  Draw a BPMN diagram with at least six steps ;  Mark delays and rework.","instructions":"[[AZ]]\n## Məqsəd\nMövcud sifariş və ya müraciət axınını seç ;  Ən azı altı addımlı BPMN sxemi hazırla ;  Gözləmə və təkrar işi işarələ.\n\n## Addım-addım icra\n1. Mövcud sifariş və ya müraciət axınını seç.\n2. Ən azı altı addımlı BPMN sxemi hazırla.\n3. Gözləmə və təkrar işi işarələ.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAs-Is BPMN və bottleneck qeydləri. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose a current application or order flow ;  Draw a BPMN diagram with at least six steps ;  Mark delays and rework.\n\n## Step-by-step\n1. Choose a current application or order flow.\n2. Draw a BPMN diagram with at least six steps.\n3. Mark delays and rework.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAs-is BPMN and bottleneck notes. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":3,"task_number":3,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Requirements Workshop","description":"[[AZ]]\nBeş funksional və üç qeyri-funksional tələb yaz ;  Hər tələb üçün mənbə və prioritet göstər ;  Qeyri-müəyyən ifadələri konkretləşdir.\n\n[[EN]]\nWrite five functional and three non-functional requirements ;  Trace every item to a source and priority ;  Replace vague wording.","instructions":"[[AZ]]\n## Məqsəd\nBeş funksional və üç qeyri-funksional tələb yaz ;  Hər tələb üçün mənbə və prioritet göstər ;  Qeyri-müəyyən ifadələri konkretləşdir.\n\n## Addım-addım icra\n1. Beş funksional və üç qeyri-funksional tələb yaz.\n2. Hər tələb üçün mənbə və prioritet göstər.\n3. Qeyri-müəyyən ifadələri konkretləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nRequirements specification. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite five functional and three non-functional requirements ;  Trace every item to a source and priority ;  Replace vague wording.\n\n## Step-by-step\n1. Write five functional and three non-functional requirements.\n2. Trace every item to a source and priority.\n3. Replace vague wording.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nRequirements specification. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":4,"task_number":4,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"User Stories and Acceptance Criteria","description":"[[AZ]]\nİstifadəçi rollarına uyğun altı user story yaz ;  Hər biri üçün Given-When-Then qəbul meyarları əlavə et ;  Təkrarlanan tələbləri birləşdir.\n\n[[EN]]\nDraft six role-based user stories ;  Add Given-When-Then acceptance tests ;  Remove duplicates.","instructions":"[[AZ]]\n## Məqsəd\nİstifadəçi rollarına uyğun altı user story yaz ;  Hər biri üçün Given-When-Then qəbul meyarları əlavə et ;  Təkrarlanan tələbləri birləşdir.\n\n## Addım-addım icra\n1. İstifadəçi rollarına uyğun altı user story yaz.\n2. Hər biri üçün Given-When-Then qəbul meyarları əlavə et.\n3. Təkrarlanan tələbləri birləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nUser story backlog. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDraft six role-based user stories ;  Add Given-When-Then acceptance tests ;  Remove duplicates.\n\n## Step-by-step\n1. Draft six role-based user stories.\n2. Add Given-When-Then acceptance tests.\n3. Remove duplicates.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nUser-story backlog. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":5,"task_number":5,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"To-Be Process Design","description":"[[AZ]]\nMövcud sxemdə iki təkmilləşdirmə seç ;  Hədəf BPMN axınını modelləşdir ;  Dəyişikliklərin risklərini izah et.\n\n[[EN]]\nChoose two improvements ;  Model the target BPMN process ;  Explain trade-offs and risks.","instructions":"[[AZ]]\n## Məqsəd\nMövcud sxemdə iki təkmilləşdirmə seç ;  Hədəf BPMN axınını modelləşdir ;  Dəyişikliklərin risklərini izah et.\n\n## Addım-addım icra\n1. Mövcud sxemdə iki təkmilləşdirmə seç.\n2. Hədəf BPMN axınını modelləşdir.\n3. Dəyişikliklərin risklərini izah et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nTo-Be BPMN və fərqlər cədvəli. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose two improvements ;  Model the target BPMN process ;  Explain trade-offs and risks.\n\n## Step-by-step\n1. Choose two improvements.\n2. Model the target BPMN process.\n3. Explain trade-offs and risks.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nTo-be BPMN and gap analysis. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":5,"task_number":6,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Prioritization and Scope","description":"[[AZ]]\nMoSCoW ilə tələbləri qruplaşdır ;  MVP sərhədlərini müəyyən et ;  Scope-dan çıxarılanları əsaslandır.\n\n[[EN]]\nGroup requirements with MoSCoW ;  Define an MVP boundary ;  Justify exclusions.","instructions":"[[AZ]]\n## Məqsəd\nMoSCoW ilə tələbləri qruplaşdır ;  MVP sərhədlərini müəyyən et ;  Scope-dan çıxarılanları əsaslandır.\n\n## Addım-addım icra\n1. MoSCoW ilə tələbləri qruplaşdır.\n2. MVP sərhədlərini müəyyən et.\n3. Scope-dan çıxarılanları əsaslandır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nPrioritetləndirmə matrisi. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nGroup requirements with MoSCoW ;  Define an MVP boundary ;  Justify exclusions.\n\n## Step-by-step\n1. Group requirements with MoSCoW.\n2. Define an MVP boundary.\n3. Justify exclusions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nPriority matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":6,"task_number":7,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"KPI and Measurement Plan","description":"[[AZ]]\nÜç ölçülə bilən KPI seç ;  Hər KPI üçün mənbə və hesablanma qaydası yaz ;  Başlanğıc və hədəf dəyərləri nümunəvi göstər.\n\n[[EN]]\nSelect three measurable KPIs ;  Define sources and formulas ;  Illustrate baseline and target with synthetic data.","instructions":"[[AZ]]\n## Məqsəd\nÜç ölçülə bilən KPI seç ;  Hər KPI üçün mənbə və hesablanma qaydası yaz ;  Başlanğıc və hədəf dəyərləri nümunəvi göstər.\n\n## Addım-addım icra\n1. Üç ölçülə bilən KPI seç.\n2. Hər KPI üçün mənbə və hesablanma qaydası yaz.\n3. Başlanğıc və hədəf dəyərləri nümunəvi göstər.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nKPI dictionary. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nSelect three measurable KPIs ;  Define sources and formulas ;  Illustrate baseline and target with synthetic data.\n\n## Step-by-step\n1. Select three measurable KPIs.\n2. Define sources and formulas.\n3. Illustrate baseline and target with synthetic data.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nKPI dictionary. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":7,"task_number":8,"difficulty":"advanced","submission_type":"multiple","is_required":true,"status":"published"},{"title":"UAT Test Scenarios","description":"[[AZ]]\nKritik üç istifadəçi ssenarisini seç ;  Altı UAT test case hazırla ;  Gözlənilən nəticə və bug qeydini nümunələndir.\n\n[[EN]]\nChoose three critical user journeys ;  Write six UAT cases ;  Record expected outcomes and sample defects.","instructions":"[[AZ]]\n## Məqsəd\nKritik üç istifadəçi ssenarisini seç ;  Altı UAT test case hazırla ;  Gözlənilən nəticə və bug qeydini nümunələndir.\n\n## Addım-addım icra\n1. Kritik üç istifadəçi ssenarisini seç.\n2. Altı UAT test case hazırla.\n3. Gözlənilən nəticə və bug qeydini nümunələndir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nUAT test matrix. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose three critical user journeys ;  Write six UAT cases ;  Record expected outcomes and sample defects.\n\n## Step-by-step\n1. Choose three critical user journeys.\n2. Write six UAT cases.\n3. Record expected outcomes and sample defects.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nUAT test matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":7,"task_number":9,"difficulty":"advanced","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Business Analysis Handoff","description":"[[AZ]]\nƏvvəlki artefaktları birləşdir ;  Dəyişiklik təklifini beş dəqiqəlik təqdimatla izah et ;  Açıq sual və riskləri qeyd et.\n\n[[EN]]\nCombine previous artifacts ;  Present recommendations in five minutes ;  Document open questions and risks.","instructions":"[[AZ]]\n## Məqsəd\nƏvvəlki artefaktları birləşdir ;  Dəyişiklik təklifini beş dəqiqəlik təqdimatla izah et ;  Açıq sual və riskləri qeyd et.\n\n## Addım-addım icra\n1. Əvvəlki artefaktları birləşdir.\n2. Dəyişiklik təklifini beş dəqiqəlik təqdimatla izah et.\n3. Açıq sual və riskləri qeyd et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nFinal BA portfolio və təqdimat. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCombine previous artifacts ;  Present recommendations in five minutes ;  Document open questions and risks.\n\n## Step-by-step\n1. Combine previous artifacts.\n2. Present recommendations in five minutes.\n3. Document open questions and risks.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nFinal BA portfolio and presentation. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":8,"task_number":10,"difficulty":"advanced","submission_type":"multiple","is_required":true,"status":"published"}]},{"slug":"talora-project-management-2026","title":"Project Management Internship","category":"Project Management","short_description":"[[AZ]]\nLayihəni planlaşdır, riskləri idarə et və komanda işini şəffaf hesabatlarla koordinasiya et.\n\n[[EN]]\nPlan projects, manage risks and coordinate delivery with clear reporting.","description":"[[AZ]]\nBu, Talora platformasının 8 həftəlik portfel-yönümlü praktik təlim proqramıdır. Məqsəd: Layihəni planlaşdır, riskləri idarə et və komanda işini şəffaf hesabatlarla koordinasiya et. Real şirkətdə işə qəbul, maaş, fərdi mentor və ya sertifikat vədi verilmir. Tapşırıqlarda yalnız sintetik, şəxsi və ya istifadəsinə icazə verilən məlumatlardan istifadə et.\n\n[[EN]]\nThis is an eight-week Talora portfolio-oriented practical training program. Goal: Plan projects, manage risks and coordinate delivery with clear reporting. It does not promise employment, salary, a dedicated mentor or a certificate. Use only synthetic, own or properly licensed data.","skills":["Project charter","WBS","Kanban","Risk management","Reporting"],"requirements":["Əsas kompüter savadlılığı, müstəqil araşdırma və qeydlərin sistemləşdirilməsi","8 həftə ərzində həftəlik praktik iş üçün vaxt ayırmaq","Mənbələri göstərmək, məxfilik və müəlliflik hüquqlarına riayət etmək"],"responsibilities":["Hər həftə mövzuya uyğun tapşırıqları yerinə yetirmək","Nəticələri yoxlanıla bilən fayl və ya linklə təqdim etmək","Mənbələri, məhdudiyyətləri və öz töhfəsini izah etmək"],"benefits":["Yoxlanıla bilən praktik layihələr və portfel","Strukturlaşdırılmış 8 həftəlik öyrənmə planı","Tapşırıq nəticələrinin şəxsi CV və portfeldə nümayişi"],"tasks":[{"title":"Project Charter","description":"[[AZ]]\nKiçik rəqəmsal layihə seç ;  Məqsəd, scope və uğur meyarlarını yaz ;  Sponsor və komanda rollarını müəyyən et.\n\n[[EN]]\nChoose a small digital project ;  Define goals, scope and success criteria ;  Identify sponsor and delivery roles.","instructions":"[[AZ]]\n## Məqsəd\nKiçik rəqəmsal layihə seç ;  Məqsəd, scope və uğur meyarlarını yaz ;  Sponsor və komanda rollarını müəyyən et.\n\n## Addım-addım icra\n1. Kiçik rəqəmsal layihə seç.\n2. Məqsəd, scope və uğur meyarlarını yaz.\n3. Sponsor və komanda rollarını müəyyən et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nProject charter. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose a small digital project ;  Define goals, scope and success criteria ;  Identify sponsor and delivery roles.\n\n## Step-by-step\n1. Choose a small digital project.\n2. Define goals, scope and success criteria.\n3. Identify sponsor and delivery roles.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nProject charter. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":1,"task_number":1,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Work Breakdown Structure","description":"[[AZ]]\nLayihəni dörd deliverable-a böl ;  Hər deliverable üçün alt işlər yaz ;  Nəticələri ölçülə bilən qəbul meyarı ilə bağla.\n\n[[EN]]\nSplit the project into four deliverables ;  Break each into tasks ;  Add measurable acceptance criteria.","instructions":"[[AZ]]\n## Məqsəd\nLayihəni dörd deliverable-a böl ;  Hər deliverable üçün alt işlər yaz ;  Nəticələri ölçülə bilən qəbul meyarı ilə bağla.\n\n## Addım-addım icra\n1. Layihəni dörd deliverable-a böl.\n2. Hər deliverable üçün alt işlər yaz.\n3. Nəticələri ölçülə bilən qəbul meyarı ilə bağla.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nWBS və task siyahısı. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nSplit the project into four deliverables ;  Break each into tasks ;  Add measurable acceptance criteria.\n\n## Step-by-step\n1. Split the project into four deliverables.\n2. Break each into tasks.\n3. Add measurable acceptance criteria.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nWBS and task list. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":2,"task_number":2,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Schedule and Dependencies","description":"[[AZ]]\nTapşırıqların asılılıqlarını yaz ;  8 həftəlik Gantt və ya timeline qur ;  Kritik riski və buffer-i işarələ.\n\n[[EN]]\nMap dependencies ;  Build an eight-week schedule ;  Mark risks and time buffer.","instructions":"[[AZ]]\n## Məqsəd\nTapşırıqların asılılıqlarını yaz ;  8 həftəlik Gantt və ya timeline qur ;  Kritik riski və buffer-i işarələ.\n\n## Addım-addım icra\n1. Tapşırıqların asılılıqlarını yaz.\n2. 8 həftəlik Gantt və ya timeline qur.\n3. Kritik riski və buffer-i işarələ.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nTimeline və dependency diaqramı. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nMap dependencies ;  Build an eight-week schedule ;  Mark risks and time buffer.\n\n## Step-by-step\n1. Map dependencies.\n2. Build an eight-week schedule.\n3. Mark risks and time buffer.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nTimeline and dependency diagram. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":3,"task_number":3,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Risk Register","description":"[[AZ]]\nƏn azı altı risk tap ;  Ehtimal və təsir səviyyəsini qiymətləndir ;  Hər riskə owner və mitigation təyin et.\n\n[[EN]]\nIdentify six risks ;  Score likelihood and impact ;  Assign owners and mitigations.","instructions":"[[AZ]]\n## Məqsəd\nƏn azı altı risk tap ;  Ehtimal və təsir səviyyəsini qiymətləndir ;  Hər riskə owner və mitigation təyin et.\n\n## Addım-addım icra\n1. Ən azı altı risk tap.\n2. Ehtimal və təsir səviyyəsini qiymətləndir.\n3. Hər riskə owner və mitigation təyin et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nRisk register. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nIdentify six risks ;  Score likelihood and impact ;  Assign owners and mitigations.\n\n## Step-by-step\n1. Identify six risks.\n2. Score likelihood and impact.\n3. Assign owners and mitigations.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nRisk register. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":4,"task_number":4,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Budget Estimation","description":"[[AZ]]\nSintetik xərc maddələri hazırla ;  Üç ssenari üçün büdcə hesabla ;  Büdcədən kənara çıxma riskini izah et.\n\n[[EN]]\nCreate synthetic cost lines ;  Estimate three budget scenarios ;  Explain overrun risk.","instructions":"[[AZ]]\n## Məqsəd\nSintetik xərc maddələri hazırla ;  Üç ssenari üçün büdcə hesabla ;  Büdcədən kənara çıxma riskini izah et.\n\n## Addım-addım icra\n1. Sintetik xərc maddələri hazırla.\n2. Üç ssenari üçün büdcə hesabla.\n3. Büdcədən kənara çıxma riskini izah et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nBudget worksheet. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCreate synthetic cost lines ;  Estimate three budget scenarios ;  Explain overrun risk.\n\n## Step-by-step\n1. Create synthetic cost lines.\n2. Estimate three budget scenarios.\n3. Explain overrun risk.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nBudget worksheet. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":5,"task_number":5,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Agile Sprint Planning","description":"[[AZ]]\nBacklog-u iki sprintə böl ;  Definition of Done müəyyən et ;  Kanban lövhəsində WIP limit qoy.\n\n[[EN]]\nSplit backlog into two sprints ;  Define Done ;  Apply a Kanban WIP limit.","instructions":"[[AZ]]\n## Məqsəd\nBacklog-u iki sprintə böl ;  Definition of Done müəyyən et ;  Kanban lövhəsində WIP limit qoy.\n\n## Addım-addım icra\n1. Backlog-u iki sprintə böl.\n2. Definition of Done müəyyən et.\n3. Kanban lövhəsində WIP limit qoy.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nSprint plan və lövhə görüntüsü. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nSplit backlog into two sprints ;  Define Done ;  Apply a Kanban WIP limit.\n\n## Step-by-step\n1. Split backlog into two sprints.\n2. Define Done.\n3. Apply a Kanban WIP limit.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nSprint plan and board snapshot. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":5,"task_number":6,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Stakeholder Updates","description":"[[AZ]]\nHəftəlik status şablonu hazırla ;  Risk, irəliləyiş və qərarları yaz ;  Bir eskalasiya mesajı nümunəsi yarat.\n\n[[EN]]\nCreate a weekly status template ;  Report progress, risks and decisions ;  Draft a sample escalation.","instructions":"[[AZ]]\n## Məqsəd\nHəftəlik status şablonu hazırla ;  Risk, irəliləyiş və qərarları yaz ;  Bir eskalasiya mesajı nümunəsi yarat.\n\n## Addım-addım icra\n1. Həftəlik status şablonu hazırla.\n2. Risk, irəliləyiş və qərarları yaz.\n3. Bir eskalasiya mesajı nümunəsi yarat.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nStatus report və kommunikasiya planı. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCreate a weekly status template ;  Report progress, risks and decisions ;  Draft a sample escalation.\n\n## Step-by-step\n1. Create a weekly status template.\n2. Report progress, risks and decisions.\n3. Draft a sample escalation.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nStatus report and communication plan. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":6,"task_number":7,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Change Request Evaluation","description":"[[AZ]]\nYeni tələb ssenarisi yarat ;  Scope/time/cost təsirini hesabla ;  Qəbul və ya rədd qərarını əsaslandır.\n\n[[EN]]\nCreate a change-request scenario ;  Estimate scope, time and cost impact ;  Justify approve or reject.","instructions":"[[AZ]]\n## Məqsəd\nYeni tələb ssenarisi yarat ;  Scope/time/cost təsirini hesabla ;  Qəbul və ya rədd qərarını əsaslandır.\n\n## Addım-addım icra\n1. Yeni tələb ssenarisi yarat.\n2. Scope/time/cost təsirini hesabla.\n3. Qəbul və ya rədd qərarını əsaslandır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nChange control log. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCreate a change-request scenario ;  Estimate scope, time and cost impact ;  Justify approve or reject.\n\n## Step-by-step\n1. Create a change-request scenario.\n2. Estimate scope, time and cost impact.\n3. Justify approve or reject.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nChange control log. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":7,"task_number":8,"difficulty":"advanced","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Delivery and Acceptance","description":"[[AZ]]\nƏsas deliverable-ları kriteriyalara görə yoxla ;  UAT checklist hazırla ;  Açıq qalan işləri handoff et.\n\n[[EN]]\nValidate deliverables against acceptance criteria ;  Prepare a UAT checklist ;  Hand off remaining work.","instructions":"[[AZ]]\n## Məqsəd\nƏsas deliverable-ları kriteriyalara görə yoxla ;  UAT checklist hazırla ;  Açıq qalan işləri handoff et.\n\n## Addım-addım icra\n1. Əsas deliverable-ları kriteriyalara görə yoxla.\n2. UAT checklist hazırla.\n3. Açıq qalan işləri handoff et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAcceptance checklist. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nValidate deliverables against acceptance criteria ;  Prepare a UAT checklist ;  Hand off remaining work.\n\n## Step-by-step\n1. Validate deliverables against acceptance criteria.\n2. Prepare a UAT checklist.\n3. Hand off remaining work.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAcceptance checklist. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":7,"task_number":9,"difficulty":"advanced","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Retrospective and Handoff","description":"[[AZ]]\nSprint nəticələrini qiymətləndir ;  Üç yaxşı və üç inkişaf sahəsini yaz ;  Növbəti layihə üçün tövsiyə ver.\n\n[[EN]]\nReview sprint results ;  List three strengths and three improvements ;  Recommend next-project actions.","instructions":"[[AZ]]\n## Məqsəd\nSprint nəticələrini qiymətləndir ;  Üç yaxşı və üç inkişaf sahəsini yaz ;  Növbəti layihə üçün tövsiyə ver.\n\n## Addım-addım icra\n1. Sprint nəticələrini qiymətləndir.\n2. Üç yaxşı və üç inkişaf sahəsini yaz.\n3. Növbəti layihə üçün tövsiyə ver.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nFinal project management report. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nReview sprint results ;  List three strengths and three improvements ;  Recommend next-project actions.\n\n## Step-by-step\n1. Review sprint results.\n2. List three strengths and three improvements.\n3. Recommend next-project actions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nFinal PM report. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":8,"task_number":10,"difficulty":"advanced","submission_type":"multiple","is_required":true,"status":"published"}]},{"slug":"talora-human-resources-2026","title":"Human Resources Internship","category":"Human Resources","short_description":"[[AZ]]\nEtik işə qəbul, onboarding və əməkdaş inkişafı proseslərini sintetik nümunələrlə layihələndir.\n\n[[EN]]\nDesign ethical recruitment, onboarding and employee-development workflows with synthetic examples.","description":"[[AZ]]\nBu, Talora platformasının 8 həftəlik portfel-yönümlü praktik təlim proqramıdır. Məqsəd: Etik işə qəbul, onboarding və əməkdaş inkişafı proseslərini sintetik nümunələrlə layihələndir. Real şirkətdə işə qəbul, maaş, fərdi mentor və ya sertifikat vədi verilmir. Tapşırıqlarda yalnız sintetik, şəxsi və ya istifadəsinə icazə verilən məlumatlardan istifadə et.\n\n[[EN]]\nThis is an eight-week Talora portfolio-oriented practical training program. Goal: Design ethical recruitment, onboarding and employee-development workflows with synthetic examples. It does not promise employment, salary, a dedicated mentor or a certificate. Use only synthetic, own or properly licensed data.","skills":["Recruitment","Skills matrix","Interview rubrics","Onboarding","Fairness"],"requirements":["Əsas kompüter savadlılığı, müstəqil araşdırma və qeydlərin sistemləşdirilməsi","8 həftə ərzində həftəlik praktik iş üçün vaxt ayırmaq","Mənbələri göstərmək, məxfilik və müəlliflik hüquqlarına riayət etmək"],"responsibilities":["Hər həftə mövzuya uyğun tapşırıqları yerinə yetirmək","Nəticələri yoxlanıla bilən fayl və ya linklə təqdim etmək","Mənbələri, məhdudiyyətləri və öz töhfəsini izah etmək"],"benefits":["Yoxlanıla bilən praktik layihələr və portfel","Strukturlaşdırılmış 8 həftəlik öyrənmə planı","Tapşırıq nəticələrinin şəxsi CV və portfeldə nümayişi"],"tasks":[{"title":"Role Analysis","description":"[[AZ]]\nNümunə junior rol seç ;  Əsas iş nəticələrini sadala ;  Vəzifəyə aid və aid olmayan tələbləri ayır.\n\n[[EN]]\nChoose a sample junior role ;  Define expected work outcomes ;  Separate job-relevant from irrelevant requirements.","instructions":"[[AZ]]\n## Məqsəd\nNümunə junior rol seç ;  Əsas iş nəticələrini sadala ;  Vəzifəyə aid və aid olmayan tələbləri ayır.\n\n## Addım-addım icra\n1. Nümunə junior rol seç.\n2. Əsas iş nəticələrini sadala.\n3. Vəzifəyə aid və aid olmayan tələbləri ayır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nRole analysis worksheet. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose a sample junior role ;  Define expected work outcomes ;  Separate job-relevant from irrelevant requirements.\n\n## Step-by-step\n1. Choose a sample junior role.\n2. Define expected work outcomes.\n3. Separate job-relevant from irrelevant requirements.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nRole analysis worksheet. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":1,"task_number":1,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Competency Matrix","description":"[[AZ]]\nBeş əsas bacarıq müəyyən et ;  Dörd pilləli səviyyə şkalası qur ;  Davranış əsaslı nümunələr yaz.\n\n[[EN]]\nIdentify five core skills ;  Define four proficiency levels ;  Add observable behavior examples.","instructions":"[[AZ]]\n## Məqsəd\nBeş əsas bacarıq müəyyən et ;  Dörd pilləli səviyyə şkalası qur ;  Davranış əsaslı nümunələr yaz.\n\n## Addım-addım icra\n1. Beş əsas bacarıq müəyyən et.\n2. Dörd pilləli səviyyə şkalası qur.\n3. Davranış əsaslı nümunələr yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nCompetency matrix. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nIdentify five core skills ;  Define four proficiency levels ;  Add observable behavior examples.\n\n## Step-by-step\n1. Identify five core skills.\n2. Define four proficiency levels.\n3. Add observable behavior examples.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nCompetency matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":2,"task_number":2,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Inclusive Job Description","description":"[[AZ]]\nAydın və inklüziv vakansiya mətni yaz ;  Obyektiv tələbləri ayır ;  Diskriminasiya yarada bilən ifadələri təmizlə.\n\n[[EN]]\nDraft an inclusive job post ;  Separate objective requirements ;  Remove discriminatory wording.","instructions":"[[AZ]]\n## Məqsəd\nAydın və inklüziv vakansiya mətni yaz ;  Obyektiv tələbləri ayır ;  Diskriminasiya yarada bilən ifadələri təmizlə.\n\n## Addım-addım icra\n1. Aydın və inklüziv vakansiya mətni yaz.\n2. Obyektiv tələbləri ayır.\n3. Diskriminasiya yarada bilən ifadələri təmizlə.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nJob description draft. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDraft an inclusive job post ;  Separate objective requirements ;  Remove discriminatory wording.\n\n## Step-by-step\n1. Draft an inclusive job post.\n2. Separate objective requirements.\n3. Remove discriminatory wording.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nJob description draft. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":3,"task_number":3,"difficulty":"beginner","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Candidate Evaluation Rubric","description":"[[AZ]]\nQiymətləndirmə meyarlarını rol ilə bağla ;  Şəffaf bal sistemi hazırla ;  İki sintetik namizədi müqayisə et.\n\n[[EN]]\nLink scoring criteria to role needs ;  Create a clear scorecard ;  Compare two fictional candidates.","instructions":"[[AZ]]\n## Məqsəd\nQiymətləndirmə meyarlarını rol ilə bağla ;  Şəffaf bal sistemi hazırla ;  İki sintetik namizədi müqayisə et.\n\n## Addım-addım icra\n1. Qiymətləndirmə meyarlarını rol ilə bağla.\n2. Şəffaf bal sistemi hazırla.\n3. İki sintetik namizədi müqayisə et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nSelection rubric. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nLink scoring criteria to role needs ;  Create a clear scorecard ;  Compare two fictional candidates.\n\n## Step-by-step\n1. Link scoring criteria to role needs.\n2. Create a clear scorecard.\n3. Compare two fictional candidates.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nSelection rubric. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":4,"task_number":4,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Structured Interview","description":"[[AZ]]\nAltı situasiya sualı yaz ;  Hər suala scoring guide əlavə et ;  İki müsahibəçi arasında kalibrasiyanı izah et.\n\n[[EN]]\nWrite six situational questions ;  Add a scoring guide ;  Explain interviewer calibration.","instructions":"[[AZ]]\n## Məqsəd\nAltı situasiya sualı yaz ;  Hər suala scoring guide əlavə et ;  İki müsahibəçi arasında kalibrasiyanı izah et.\n\n## Addım-addım icra\n1. Altı situasiya sualı yaz.\n2. Hər suala scoring guide əlavə et.\n3. İki müsahibəçi arasında kalibrasiyanı izah et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nStructured interview kit. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite six situational questions ;  Add a scoring guide ;  Explain interviewer calibration.\n\n## Step-by-step\n1. Write six situational questions.\n2. Add a scoring guide.\n3. Explain interviewer calibration.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nStructured interview kit. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":5,"task_number":5,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Onboarding Journey","description":"[[AZ]]\nİlk 30 gün üçün plan hazırla ;  Təlim və resurs ehtiyaclarını cədvəlləşdir ;  7 və 30-cu gün check-in forması yarat.\n\n[[EN]]\nPlan the first 30 days ;  Map training and resources ;  Draft day-seven and day-thirty check-ins.","instructions":"[[AZ]]\n## Məqsəd\nİlk 30 gün üçün plan hazırla ;  Təlim və resurs ehtiyaclarını cədvəlləşdir ;  7 və 30-cu gün check-in forması yarat.\n\n## Addım-addım icra\n1. İlk 30 gün üçün plan hazırla.\n2. Təlim və resurs ehtiyaclarını cədvəlləşdir.\n3. 7 və 30-cu gün check-in forması yarat.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\n30-day onboarding plan. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nPlan the first 30 days ;  Map training and resources ;  Draft day-seven and day-thirty check-ins.\n\n## Step-by-step\n1. Plan the first 30 days.\n2. Map training and resources.\n3. Draft day-seven and day-thirty check-ins.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\n30-day onboarding plan. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":5,"task_number":6,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Learning Needs Assessment","description":"[[AZ]]\nSintetik komanda ssenarisi qur ;  Skill gap təhlili et ;  Üç təlim müdaxiləsini prioritetləşdir.\n\n[[EN]]\nUse a fictional team scenario ;  Analyze skill gaps ;  Prioritize three learning interventions.","instructions":"[[AZ]]\n## Məqsəd\nSintetik komanda ssenarisi qur ;  Skill gap təhlili et ;  Üç təlim müdaxiləsini prioritetləşdir.\n\n## Addım-addım icra\n1. Sintetik komanda ssenarisi qur.\n2. Skill gap təhlili et.\n3. Üç təlim müdaxiləsini prioritetləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nL&D needs analysis. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nUse a fictional team scenario ;  Analyze skill gaps ;  Prioritize three learning interventions.\n\n## Step-by-step\n1. Use a fictional team scenario.\n2. Analyze skill gaps.\n3. Prioritize three learning interventions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nL&D needs analysis. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","week_number":6,"task_number":7,"difficulty":"intermediate","submission_type":"multiple","is_required":true,"status":"published"},{"title":"Anonymous Feedback Survey","description":"[[AZ]]\nİnklüziv qısa sorğu hazırla ;  Fərdi identifikasiya riskini araşdır ;  Sintetik nəticələri qrafiklə ümumiləşdir.\n\n[[EN]]\nDesign a short inclusive survey ;  Assess identification risks ;  Summarize synthetic findings in a chart.","instructions":"[[AZ]]\n## Məqsəd\nİnklüziv qısa sorğu hazırla ;  Fərdi identifikasiya riskini araşdır ;  Sintetik nəticələri qrafiklə ümumiləşdir.\n\n## Addım-addım icra\n1. İnklüziv qısa sorğu hazırla.\n2. Fərdi identifikasiya riskini araşdır.\n3. Sintetik nəticələri qrafiklə ümumiləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nSurvey and privacy note. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yox